/**
 * Um item por vendedor a avisar — e falha ALTO quando a lista não veio.
 *
 * Quem decide o que é venda incompleta é o banco (`vw_vendas_incompletas`),
 * e quem monta o texto é o site. Aqui só se entrega.
 *
 * Status fora de 200 estoura em vez de seguir vazio: execução verde com zero
 * envio é o modo de falha que já aconteceu neste projeto, e num aviso de
 * cadastro ele é invisível por semanas.
 */

// >>> PREENCHA: WhatsApp de quem cuida do cadastro, só dígitos com DDI.
//     Ex.: '5541999998888'. Vazio = o aviso de gestão não é enviado (e sai
//     registrado no ramo "Não enviado"). Deliberadamente uma constante, e não
//     `$env`: nesta instância o acesso a variável de ambiente em nó Code não
//     está provado, e se estiver bloqueado a execução inteira estoura.
const WHATSAPP_GESTAO = '';
const r = $input.first().json;
const status = r.statusCode ?? 0;
const corpo = r.body ?? {};
if (status !== 200 || corpo.ok !== true) {
  throw new Error('Lista indisponível: HTTP ' + status + ' — ' + JSON.stringify(corpo).slice(0, 300));
}

const avisos = Array.isArray(corpo.avisos) ? corpo.avisos : [];
const semTelefone = Array.isArray(corpo.sem_telefone) ? corpo.sem_telefone : [];
const semAtribuicao = Array.isArray(corpo.sem_atribuicao) ? corpo.sem_atribuicao : [];

// Nada a avisar é resultado bom, não erro — e precisa passar sem envio.
if (avisos.length === 0 && semTelefone.length === 0 && semAtribuicao.length === 0) {
  return [];
}

const itens = avisos.map((a) => ({
  json: { ...a, tipo: 'vendedor' },
}));

// O que NÃO dá para avisar vira um aviso para a gestão. Sem isto, vendedor
// sem telefone e venda sem dono somem em silêncio — e silêncio aqui é o
// cadastro nunca sendo corrigido.
if (semTelefone.length > 0 || semAtribuicao.length > 0) {
  const linhas = [];
  if (semTelefone.length > 0) {
    linhas.push('Sem WhatsApp cadastrado (não foram avisados):');
    for (const s of semTelefone) {
      linhas.push('• ' + s.vendedor_nome + ' — ' + s.vendas + ' venda(s)');
    }
    linhas.push('');
    linhas.push('O telefone se cadastra no painel, em Usuários.');
  }
  if (semAtribuicao.length > 0) {
    if (linhas.length > 0) linhas.push('');
    linhas.push('Vendas sem vendedor atribuído (ninguém foi cobrado):');
    for (const s of semAtribuicao) {
      linhas.push('• ' + s.cliente_nome + (s.placa ? ' (' + s.placa + ')' : ''));
    }
  }
  itens.push({
    json: {
      tipo: 'gestao',
      vendedor_nome: 'Gestão',
      numero_whatsapp: WHATSAPP_GESTAO,
      mensagem: linhas.join('\n'),
    },
  });
}

return itens;

/**
 * Fecha o rastro de cada envio.
 *
 * Diferente do orquestrador do cliente, aqui NÃO há desfecho a devolver: o
 * aviso ao vendedor não consome janela de ninguém e não entra em régua de
 * frequência. Se falhar, a venda continua incompleta e a rotina avisa de
 * novo amanhã — que é o comportamento certo para uma cobrança de cadastro.
 *
 * O que importa é o registro ficar legível na execução.
 */
const resposta = $json;
const original = $('Um por vendedor').item.json;
const status = resposta.statusCode ?? 0;
return {
  json: {
    tipo: original.tipo,
    vendedor_nome: original.vendedor_nome,
    vendas: original.vendas ?? null,
    campos_pendentes: original.campos_pendentes ?? null,
    status,
    enviado: status < 300,
  },
};

/**
 * Quem não tinha número. Não é erro de execução — é cadastro faltando —,
 * mas precisa aparecer, senão o aviso de gestão some justamente quando o
 * telefone da gestão é o que está faltando.
 */
return {
  json: {
    tipo: $json.tipo,
    vendedor_nome: $json.vendedor_nome,
    enviado: false,
    motivo: $json.tipo === 'gestao'
      ? 'WHATSAPP_GESTAO não preenchido no nó "Um por vendedor"'
      : 'vendedor sem telefone em profiles',
  },
};
